  "/lib/components/svforge/tiptap/tiptap-extensions.ts": "/**\n * SVForge Tiptap Extensions\n */\nimport { Node, mergeAttributes } from '@tiptap/core';\nimport { clampHeadingLevel } from './render-tiptap';\n\n// ============================================================\n// Visual Heading - semantic heading element styled by Tailwind Typography\n// ============================================================\n\nexport interface VisualHeadingOptions {\n\tHTMLAttributes: Record<string, string>;\n\tlevels: number[];\n}\n\ndeclare module '@tiptap/core' {\n\tinterface Commands<ReturnType> {\n\t\tvisualHeading: {\n\t\t\tsetVisualHeading: (attributes: { level: number }) => ReturnType;\n\t\t\ttoggleVisualHeading: (attributes: { level: number }) => ReturnType;\n\t\t\tunsetVisualHeading: () => ReturnType;\n\t\t};\n\t}\n}\n\nexport const VisualHeading = Node.create<VisualHeadingOptions>({\n\tname: 'heading',\n\n\taddOptions() {\n\t\treturn {\n\t\t\tHTMLAttributes: {},\n\t\t\tlevels: [1, 2, 3, 4, 5, 6]\n\t\t};\n\t},\n\n\tcontent: 'inline*',\n\tgroup: 'block',\n\tdefining: true,\n\n\taddAttributes() {\n\t\treturn {\n\t\t\tlevel: {\n\t\t\t\tdefault: 1,\n\t\t\t\trendered: false\n\t\t\t}\n\t\t};\n\t},\n\n\tparseHTML() {\n\t\treturn this.options.levels.map((level) => ({\n\t\t\ttag: `h${level}`,\n\t\t\tattrs: { level }\n\t\t}));\n\t},\n\n\trenderHTML({ node, HTMLAttributes }) {\n\t\tconst level = clampHeadingLevel(node.attrs.level);\n\t\treturn [`h${level}`, mergeAttributes(this.options.HTMLAttributes, HTMLAttributes), 0];\n\t},\n\n\taddCommands() {\n\t\treturn {\n\t\t\tsetVisualHeading:\n\t\t\t\t(attributes) =>\n\t\t\t\t({ commands }) => {\n\t\t\t\t\tif (!this.options.levels.includes(attributes.level)) {\n\t\t\t\t\t\treturn false;\n\t\t\t\t\t}\n\t\t\t\t\treturn commands.setNode(this.name, attributes);\n\t\t\t\t},\n\t\t\ttoggleVisualHeading:\n\t\t\t\t(attributes) =>\n\t\t\t\t({ commands }) => {\n\t\t\t\t\tif (!this.options.levels.includes(attributes.level)) {\n\t\t\t\t\t\treturn false;\n\t\t\t\t\t}\n\t\t\t\t\treturn commands.toggleNode(this.name, 'paragraph', attributes);\n\t\t\t\t},\n\t\t\tunsetVisualHeading:\n\t\t\t\t() =>\n\t\t\t\t({ commands }) => {\n\t\t\t\t\treturn commands.setNode('paragraph');\n\t\t\t\t}\n\t\t};\n\t}\n});\n",
  "/lib/components/svforge/tiptap/toolbar-state.ts": "export interface ToolbarState {\n\tactiveFormats: string[];\n\tactiveHeading: string[];\n\tactiveLists: string[];\n\tactiveBlocks: string[];\n\tactiveLink: boolean;\n}\n\ninterface EditorStateReader {\n\tisActive: (type: string) => boolean;\n\tgetAttributes: (type: string) => { level?: unknown };\n}\n\nconst EMPTY_TOOLBAR_STATE: ToolbarState = {\n\tactiveFormats: [],\n\tactiveHeading: [],\n\tactiveLists: [],\n\tactiveBlocks: [],\n\tactiveLink: false\n};\n\n/** Map the current Tiptap selection to the toolbar's controlled toggle values. */\nexport function getToolbarState(editor?: EditorStateReader | null): ToolbarState {\n\tif (!editor) return EMPTY_TOOLBAR_STATE;\n\n\tconst activeFormats = ['bold', 'italic', 'underline', 'strike'].filter((mark) => editor.isActive(mark));\n\tconst headingLevel = editor.getAttributes('heading')?.level;\n\tconst activeHeading =\n\t\teditor.isActive('heading') && typeof headingLevel === 'number' && [1, 2, 3].includes(headingLevel)\n\t\t\t? [String(headingLevel)]\n\t\t\t: [];\n\n\treturn {\n\t\tactiveFormats,\n\t\tactiveHeading,\n\t\tactiveLists: ['bulletList', 'orderedList'].filter((list) => editor.isActive(list)),\n\t\tactiveBlocks: ['blockquote', 'codeBlock'].filter((block) => editor.isActive(block)),\n\t\tactiveLink: editor.isActive('link')\n\t};\n}\n"
